// Command interface and history (spec §6.3). Commands are built from Immer recipes; applying one
// records forward and inverse patches, so `invert` is exact and redo replays the same patches
// (ids generated by a command factory therefore stay stable across undo/redo).
import { applyPatches, enablePatches, produceWithPatches, type Patch } from 'immer';
import type { Model } from '../model/types';

enablePatches();

export interface Command {
  /** Shown in the undo menu, e.g. "Move 3 elements". */
  label: string;
  /** Pure: returns the new model. */
  apply(m: Model): Model;
  /** The command that undoes the last `apply`; computed at apply time. */
  invert(before: Model): Command;
}

class PatchReplay implements Command {
  constructor(
    readonly label: string,
    private readonly patches: Patch[],
    private readonly inverse: Patch[],
  ) {}

  apply(m: Model): Model {
    return applyPatches(m, this.patches);
  }

  invert(): Command {
    return new PatchReplay(this.label, this.inverse, this.patches);
  }
}

class RecipeCommand implements Command {
  private patches: Patch[] | null = null;
  private inverse: Patch[] | null = null;

  constructor(
    readonly label: string,
    readonly recipe: (draft: Model) => void,
  ) {}

  apply(m: Model): Model {
    const [next, patches, inverse] = produceWithPatches(m, this.recipe);
    this.patches = patches;
    this.inverse = inverse;
    return next;
  }

  invert(): Command {
    if (!this.patches || !this.inverse) throw new Error(`invert() before apply(): ${this.label}`);
    return new PatchReplay(this.label, this.inverse, this.patches);
  }

  /** Forward replay of the last apply (used for redo). */
  replay(): Command {
    if (!this.patches || !this.inverse) throw new Error(`replay() before apply(): ${this.label}`);
    return new PatchReplay(this.label, this.patches, this.inverse);
  }
}

/** Builds a command from an Immer recipe. Generate ids before calling, not inside the recipe. */
export function command(label: string, recipe: (draft: Model) => void): Command {
  return new RecipeCommand(label, recipe);
}

/**
 * Several commands as one undo step (e.g. paste = add elements + nodes + connections). Parts must
 * be fresh commands from `command()`; their recipes run in order on one draft.
 */
export function compound(label: string, parts: Command[]): Command {
  const recipes = parts.map((p) => {
    if (!(p instanceof RecipeCommand)) throw new Error('compound() needs recipe commands');
    return p.recipe;
  });
  return command(label, (draft) => {
    for (const r of recipes) r(draft);
  });
}

export interface HistoryEntry {
  seq: number;
  redo: Command;
  undo: Command;
}

export const HISTORY_LIMIT = 200;

let seqCounter = 0;

/** Applies `cmd`, returning the new model and the history entry for it. */
export function execute(model: Model, cmd: Command): { model: Model; entry: HistoryEntry } {
  const next = cmd.apply(model);
  const undo = cmd.invert(model);
  const redo = cmd instanceof RecipeCommand ? cmd.replay() : cmd;
  return { model: next, entry: { seq: ++seqCounter, redo, undo } };
}
